// ── 1. Inputs ──────────────────────────────────────────────────────────────
const businessEvents = $('Google Calendar - Business').all();
const personalEvents = $('Google Calendar - Personal').all();
const holidayEvents  = $('Google Calendar - NZ Holidays').all();

let sonyaEvents = [];
try { sonyaEvents = $('Google Calendar - Sonya').all(); } catch (e) {}

let birthdayEvents = [];
try { birthdayEvents = $('Google Calendar - Birthdays').all(); } catch (e) {}

let familyEvents = [];
try { familyEvents = $('Google Calendar - Parsons Family').all(); } catch (e) {}

// ── 2. Deduplication ──────────────────────────────────────────────────────────────────
function deduplicateEvents(events) {
  const seen = new Set();
  return events.filter(item => {
    const key = item.json.iCalUID || item.json.id;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

const business  = deduplicateEvents(businessEvents);
const personal  = deduplicateEvents(personalEvents);
const holidays  = deduplicateEvents(holidayEvents);
const sonya     = deduplicateEvents(sonyaEvents);
const birthdays = deduplicateEvents(birthdayEvents);
const family    = deduplicateEvents(familyEvents);

// ── 3. Timestamps stay in UTC throughout — converted to NZT only at final briefing render ──
// No timezone conversion here. UTC ISO strings passed through as-is.

// ── 4. Helpers ──────────────────────────────────────────────────────────────────
function decodeEntities(str) {
  if (!str) return '';
  return str
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/g, "'")
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(parseInt(code, 10)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)));
}

function isValidEvent(e) {
  const hasId    = !!(e.id || e.iCalUID);
  const hasStart = !!(e.start?.dateTime || e.start?.date);
  const hasTitle = !!(e.summary && e.summary.trim());
  return hasId && hasStart && hasTitle;
}

function eventToObject(item, calendar) {
  const e = item.json;
  const startRaw = e.start?.dateTime || e.start?.date || null;
  const endRaw   = e.end?.dateTime   || e.end?.date   || null;
  const isAllDay = !e.start?.dateTime;

  // Keep all timed datetimes as UTC ISO (ensure Z suffix). All-day dates stay as plain date strings.
  const toUTC = (s) => {
    if (!s) return null;
    if (isAllDay) return s;
    return new Date(s).toISOString();  // parse any offset correctly, emit clean UTC Z
  };

  const startUTC = toUTC(startRaw);
  const endUTC   = toUTC(endRaw);

  let durationMinutes = null;
  if (!isAllDay && startRaw && endRaw) {
    durationMinutes = Math.round((new Date(endRaw) - new Date(startRaw)) / 60000);
  }

  return {
    source:           'calendar',
    event_id:         e.id || null,
    timestamp:        startUTC,
    title:            decodeEntities(e.summary || '(No title)'),
    calendar:         calendar,
    timezone:         'UTC',
    all_day:          isAllDay,
    start:            startUTC,
    end:              endUTC,
    duration_minutes: durationMinutes,
    location:         decodeEntities(e.location || ''),
    description:      decodeEntities((e.description || '').substring(0, 300)),
    status:           e.status || null,
    event_type:       e.eventType || null,
    url:              e.htmlLink || null
  };
}

// ── 5. Build unified events array, filtering nulls ─────────────────────────────────
const events = [
  ...business.filter(e  => isValidEvent(e.json)).map(e  => eventToObject(e, 'work')),
  ...personal.filter(e  => isValidEvent(e.json)).map(e  => eventToObject(e, 'personal')),
  ...family.filter(e    => isValidEvent(e.json)).map(e  => eventToObject(e, 'family')),
  ...sonya.filter(e     => isValidEvent(e.json)).map(e  => eventToObject(e, 'sonya')),
  ...birthdays.filter(e => isValidEvent(e.json)).map(e  => eventToObject(e, 'birthdays')),
  ...holidays.filter(e  => isValidEvent(e.json)).map(e  => eventToObject(e, 'holidays')),
];

// Sort ascending by start timestamp
events.sort((a, b) => {
  if (!a.timestamp) return 1;
  if (!b.timestamp) return -1;
  return a.timestamp.localeCompare(b.timestamp);
});

// ── 6. Wrap in fenced JSON block for Obsidian ─────────────────────────────────────────
const fence = '```';
const content = `${fence}json\n${JSON.stringify(events, null, 2)}\n${fence}`;

return [{ json: { content } }];
